{
    const int margin = FromDIP(16), gap = FromDIP(8), height = GetClientSize().y;
    auto place = [height](HeaderButton* button, int x, int width = -1) {
        wxSize size = button->GetBestSize();
        if (width >= 0) size.x = width;
        button->SetSize(x,(height-size.y)/2,size.x,size.y);
    };
    int right = GetClientSize().x-margin;
    if (m_agent_toggle->IsShown()) {
        right -= m_agent_toggle->GetBestSize().x;
        place(m_agent_toggle,right);
        right -= gap;
    }
    right -= m_overflow_button->GetBestSize().x;
    place(m_overflow_button,right);
    right -= gap;
    if (m_menu_button->IsShown()) {
        right -= m_menu_button->GetBestSize().x;
        place(m_menu_button,right);
    }
    right -= m_slice_button->GetBestSize().x;
    place(m_slice_button,right);
    int home_x = margin;
    if (m_left_pane_toggle->IsShown()) {
        place(m_left_pane_toggle, home_x);
        home_x += m_left_pane_toggle->GetBestSize().x + gap;
    }
    place(m_home_button,home_x);
    const int left = home_x+m_home_button->GetBestSize().x+gap;
    const int available = std::max(0,right-gap-left);
    const int width = std::min(m_chip->GetBestSize().x,available);
    const wxSize chip = m_chip->GetBestSize();
    const int chip_x = left+(available-width)/2;
    m_chip->SetSize(chip_x,(height-chip.y)/2,width,chip.y);
    // The title takes what is left between the arrow and the chip, which
    // stays centred whatever the name's length.
    m_title_left  = home_x+m_home_button->GetBestSize().x+FromDIP(m_theme.metrics().space_3);
    m_title_right = std::max(m_title_left, chip_x-gap);
    Refresh();
}

void StatusRow::paint_title(wxDC& dc) const
{
    const auto& p = m_theme.palette(m_dark);
    const int space = m_title_right-m_title_left;
    if (space <= 0)
        return;
    const wxString state = save_state();
    const int state_gap = FromDIP(m_theme.metrics().space_2);
    dc.SetFont(m_theme.font(TextRole::Body));
    const int state_width = state.empty() ? 0 : dc.GetTextExtent(state).x+state_gap;
    dc.SetFont(m_theme.font(TextRole::BodyBold));
    // The name keeps the room it needs first; the save state follows it only
    // when both fit.
    const bool with_state = !state.empty() && dc.GetTextExtent(project_name()).x+state_width <= space;
    const wxString name = wxControl::Ellipsize(project_name(), dc, wxELLIPSIZE_END, space-(with_state ? state_width : 0));
    const wxSize name_size = dc.GetTextExtent(name);
    const int height = GetClientSize().y;
    dc.SetTextForeground(p.text_primary);
    dc.DrawText(name, m_title_left, (height-name_size.y)/2);
    if (!with_state)
        return;
    dc.SetFont(m_theme.font(TextRole::Body));
    const bool failed = m_autosave != nullptr && m_autosave->state() == Workspace::ProjectAutosave::State::Failed;
    dc.SetTextForeground(failed ? p.status_danger : p.text_secondary);
    dc.DrawText(state, m_title_left+name_size.x+state_gap, (height-dc.GetTextExtent(state).y)/2);
}

wxString StatusRow::project_name() const
{
    const wxString name = m_autosave != nullptr ? wxString::FromUTF8(m_autosave->project_name())
                                                : m_plater.get_project_name();
    return name.empty() ? _L("Untitled") : name;
}

wxString StatusRow::save_state() const
{
    if (m_autosave == nullptr)
        return m_plater.is_project_dirty() ? _L("Unsaved changes") : wxString();
    switch (m_autosave->state()) {
    case Workspace::ProjectAutosave::State::Saving: return _L("Saving…");

    decoration.detail        = nozzle;
    decoration.detail_inline = true;
    if (from_file) {
        decoration.detail_more = _L("from the file");
        decoration.icon_tone   = StatusTone::Warning;
    }
    decoration.trailing      = HeaderIcon::Caret;
    m_printer->set_decoration(std::move(decoration));
    // The tooltip carries the full text the chip may have ellipsized. It says
    // what is selected and nothing about whether it is loaded: the chip makes
    // no claim about the physical machine.
    m_printer->SetToolTip(tooltip.empty() ? name : tooltip);
    InvalidateBestSize();
    layout();
}

void PrinterFilamentChip::set_filaments(const FilamentChipModel& model, const wxString& label, const wxString& tooltip)
{
    m_filament->SetLabel(label.empty() ? _L("Select filament") : label);
    HeaderRowDecoration decoration;
    for (const ChipDot& dot : model.dots)
        decoration.slot_dots.push_back({wxColour(wxString::FromUTF8(dot.colour)), dot.faded});
    if (model.folded > 0)
        decoration.slot_more = wxString::Format("+%d", int(model.folded));
    decoration.small_slot_dots = model.shrunk;
    decoration.trailing        = HeaderIcon::Caret;
    m_filament->set_decoration(std::move(decoration));
    m_filament->SetToolTip(tooltip.empty() ? label : tooltip);
    InvalidateBestSize();
    layout();
}

void PrinterFilamentChip::set_dark(bool dark)
{
    m_printer->set_dark(dark);
    m_filament->set_dark(dark);
    Refresh();
}

wxSize PrinterFilamentChip::DoGetBestSize() const
{
    const wxSize left = m_printer->GetBestSize(), right = m_filament->GetBestSize();
    return {left.x + right.x, std::max(left.y, right.y)};
}

wxBitmap PrinterFilamentChip::snapshot()
{
    const wxBitmap left = m_printer->snapshot(), right = m_filament->snapshot();
    wxBitmap combined(left.GetWidth() + right.GetWidth(), std::max(left.GetHeight(), right.GetHeight()));
    wxMemoryDC dc(combined);
    dc.DrawBitmap(left, 0, 0);
    dc.DrawBitmap(right, left.GetWidth(), 0);
    dc.SelectObject(wxNullBitmap);
    return combined;
}

void PrinterFilamentChip::layout()
{
    const wxSize size = GetClientSize();
    if (size.x <= 0) return;
    // Under pressure the filament half gives up width first: a long preset
    // name, such as a calibrated copy's, ends in its ellipsis (the tooltip
    // has it whole) while the printer keeps its name. The printer yields
    // only past half the chip, so neither half collapses.
    const int wanted_left  = m_printer->GetBestSize().x;
    const int wanted_right = m_filament->GetBestSize().x;
    const int left = wanted_left + wanted_right <= size.x ? wanted_left
                                                          : std::min(wanted_left, std::max(size.x / 2, size.x - wanted_right));
    m_printer->SetSize(0, 0, left, size.y);
    m_filament->SetSize(left, 0, size.x - left, size.y);
}

} // namespace Slic3r::GUI::JusPrin

